import{_ as o,l as i,o as e,c as s,v as t,p as l,x as r,d,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"工具变量与弱工具","description":"","frontmatter":{"title":"工具变量与弱工具","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/iv-weak-instruments.md","filePath":"econ/iv-weak-instruments.md","lastUpdated":1789023840000}'),c={name:"econ/iv-weak-instruments.md"};function h(E,a,u,S,A,B){const n=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="工具变量与弱工具" tabindex="-1">工具变量与弱工具 <a class="header-anchor" href="#工具变量与弱工具" aria-label="Permalink to &quot;工具变量与弱工具&quot;">​</a></h1><div class="epigraph"><p>工具必须与内生回归元相关、只通过它进入结果方程；相关太弱时，2SLS 偏向 OLS，置信区间的名义覆盖是假的。</p><footer>—— Wright 供给弹性的工具传统；Angrist and Krueger, Does Compulsory School Attendance Affect Schooling and Earnings?, QJE 1991；Staiger and Stock, Econometrica 1997</footer></div><p><a href="/econ/ovb-measurement-error">上一课</a>给出 OVB 与衰减，没有给出外生来源。本课缺口是工具变量：用 \\(Z\\) 提供的外生变异识别对 \\(X\\) 的效应，并标明弱工具何时把这套装置毁掉。两阶段最小二乘的过度识别检验下一课再写；本课先钉相关与排除。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>结构 \\(Y=\\beta X+u\\)，\\(\\mathrm{Cov}(X,u)\\neq 0\\)。若存在 \\(Z\\) 满足 \\(\\mathrm{Cov}(Z,u)=0\\)（排除 / 外生）且 \\(\\mathrm{Cov}(Z,X)\\neq 0\\)（相关），则</p> \\[\\beta=\\frac{\\mathrm{Cov}(Z,Y)}{\\mathrm{Cov}(Z,X)}. \\]<p>Wald 比在 \\(Z\\) 二值时就是这个比。缺口不是再讲教育回报从哪来，而是：排除是不可检验的（恰好识别时），相关是可检验的，弱相关让分母近零，估计量噪声极大且偏向 OLS。</p><p>Angrist–Krueger（1991）用出生季度当入学年龄与义务教育的工具：相关来自制度，排除来自「季度不直接进工资」——后一条立刻被质疑（季节、家庭背景）。Bound、Jaeger 与 Baker（1995）指出：第一阶段若弱，即便 \\(Z\\) 有轻微排除偏离，偏误也被放大。Staiger–Stock：经验规则「\\(F\\gt 10\\)」是弱工具诊断的入口，不是定理。</p><p><span class="marginnote">排除失败：季度通过季节性就业直接进 \\(Y\\)。相关失败：义务教育对多数人是松约束。两失败可以同时发生。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一阶段 \\(X=\\pi Z+v\\)。\\(\\pi\\neq 0\\) 是秩条件。恰好识别时 IV = 间接最小二乘 = 2SLS。异质效应下恰好识别 IV 估计 LATE——下一课序后段再展开，本课先用常数 \\(\\beta\\)。弱工具：Anderson–Rubin 对恰好识别稳健；Stock–Yogo 给出最大相对偏误与实际水平的临界值；Kleibergen–Paap 在聚类下替代 Cragg–Donald。</p>',11)),(e(),l(p,null,{default:r(()=>[m(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E5%B7%A5%E5%85%B7%20Z%22%5D%20--%3E%20FS%5B%22%E7%AC%AC%E4%B8%80%E9%98%B6%E6%AE%B5%3A%20%E7%9B%B8%E5%85%B3%22%5D%0A%20%20Z%20--%3E%20EX%5B%22%E6%8E%92%E9%99%A4%3A%20%E4%B8%8D%E8%BF%9B%E7%BB%93%E6%9E%84%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20FS%20--%3E%20IV%5B%22IV%20%2F%20Wald%22%5D%0A%20%20EX%20--%3E%20IV%0A%20%20WEAK%5B%22%CF%80%20%E2%89%88%200%22%5D%20--%3E%20BIAS%5B%22%E5%81%8F%E5%90%91%20OLS%2C%20%E8%A6%86%E7%9B%96%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>量化栏的<a href="/quant/iv-finance">金融 IV</a>把同一装置用到公司金融与资产定价回归；本课写识别语言，不重写那些回归表，也不进限价簿。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是只通过 \\(X\\) 的通道。\\(Z\\) 移动 \\(X\\) 的外生部分，\\(\\mathrm{Cov}(Z,Y)\\) 把 \\(\\beta\\) 乘在这段移动上。弱工具使这段移动相对于噪声太小，有限样本里第一阶段估计的 \\(\\hat\\pi\\) 把噪声带进第二阶段——与 OLS 的内生偏误同方向靠拢。许多工具堆上去、每个都弱，问题更重，那是下一课过度识别要管的。</p><p>与<a href="/econ/lucas-critique">卢卡斯批判</a>：工具若是政策规则的一部分，规则一变 \\(\\pi\\) 与排除一起变。IV 不是自动结构。</p><p><span class="marginnote">单调性（Imbens–Angrist）在异质下保证 LATE 是编译器的加权；违反则 IV 是符号不定的混合。本课常数 \\(\\beta\\) 下还不需要，但弱工具与异质会纠缠。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把「找一个与 \\(X\\) 相关的变量」当成研究设计。不报某个义务教育 \\(F\\) 统计量的新数字。排除在恰好识别下不可检验，只能讲机制故事与安慰剂（\\(Z\\) 对未处理结果、对预定期）。下一课 2SLS 在过度识别下给出 Hansen–Sargan，仍检验的是<strong>所有工具联合</strong>与误差不相关，不是单条排除为真。</p><p>后课默认：写 IV 先写排除机制与第一阶段强度；\\(F\\) 过低则改用弱工具稳健推断，或承认识别失败。2SLS 与过度识别下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IV 比：\\(\\mathrm{Cov}(Z,Y)/\\mathrm{Cov}(Z,X)\\)；排除加相关。</li><li>弱工具：2SLS 偏向 OLS，名义 \\(t\\) 不可用。</li><li>恰好识别时排除不可检验；相关可检验。</li><li>量化栏金融 IV 是应用，不是另一套定义。</li><li>出处：Angrist and Krueger, <em>QJE</em> 1991；Bound, Jaeger and Baker, <em>JASA</em> 1995；Staiger and Stock, <em>Econometrica</em> 1997；Stock and Yogo 弱工具临界值。</li></ul>',10))])}const f=o(c,[["render",h]]);export{g as __pageData,f as default};
